minimal.config.yaml:
{
  "terminal": {
    "backend": "local"
  },
  "agent": {
    "api_max_retries": 30,
    "disabled_toolsets": [
      "browser",
      "cronjob",
      "connections"
    ]
  },
  "approvals": {
    "mode": "off"
  },
  "tools": {
    "tool_search": {
      "enabled": "off"
    }
  },
  "model": {
    "default": "openhut-test-sonnet",
    "provider": "custom",
    "base_url": "http://10.200.7.1:8081/test-llm/v1",
    "api_key": "ag_golden00.token",
    "context_length": 200000
  },
  "plugins": {
    "entries": {
      "claude-subscription-directsdk-experimental": {
        "settings": {
          "relay_upstream": "http://10.200.7.1:8081/u/anthropic"
        }
      },
      "openhut": {
        "allow_gateway_injection": true,
        "settings": {
          "tools": [
            {
              "name": "post_message",
              "description": "Post a message in one of your own channels without being asked there first, like a report for the team. get_self's postTo lists where you can post. You can't post anywhere else.",
              "parameters": {
                "type": "object",
                "properties": {
                  "channel": {
                    "type": "string",
                    "maxLength": 40,
                    "description": "The channel id from postTo."
                  },
                  "chat": {
                    "description": "The chat from postTo. Leave out for the channel's first one.",
                    "type": "string",
                    "maxLength": 200
                  },
                  "message": {
                    "type": "string",
                    "minLength": 1,
                    "description": "What to post, in plain words."
                  }
                },
                "required": [
                  "channel",
                  "message"
                ]
              }
            }
          ],
          "hooks": [
            "pre_gateway_dispatch",
            "transform_llm_output",
            "subagent_start",
            "subagent_stop"
          ],
          "slack_actions": [
            "card:"
          ]
        }
      }
    },
    "enabled": [
      "openhut"
    ]
  },
  "platform_toolsets": {
    "api_server": [
      "hermes-api-server",
      "openhut",
      "openhut-local"
    ]
  },
  "delegation": {
    "max_spawn_depth": 1,
    "max_concurrent_children": 1000,
    "gateway_mode": "inline"
  },
  "mcp_servers": {
    "openhut": {
      "url": "http://10.200.7.1:8081/api/v1/mcp",
      "headers": {
        "Authorization": "Agent ag_golden00.token"
      }
    }
  }
}

